window.RTLBenchLSData.register("assets/d39957226f71483e9d82690f84f50b737b62a548e36becc52c068c6fcaf98eb0.txt","module IOBUFDS (O, IO, IOB, I, T);\n\n`ifdef XIL_TIMING\n    parameter LOC = \"UNPLACED\";\n`endif // `ifdef XIL_TIMING\n    parameter DIFF_TERM = \"FALSE\";\n    parameter DQS_BIAS = \"FALSE\";\n    parameter IBUF_LOW_PWR = \"TRUE\";\n    parameter IOSTANDARD = \"DEFAULT\";\n    parameter SLEW = \"SLOW\";\n\n   localparam MODULE_NAME = \"IOBUFDS\";\n\n\n    output O;\n    inout  IO, IOB;\n    input  I, T;\n\n   assign O = ~(IO & ~IOB);\n   assign IO = T ? 1'bz : I;\n   assign IOB = T ? 1'bz : ~I;\n   \nendmodule");
